/*
 * mtp-example — a starter µTest++ test for this board.
 * GENERATED by micro-os-scaffold (--micro-test-plus).
 *
 * It is an ordinary test directory: the port's builder makes its images and
 * the platform registers them with CTest like every other test. Inside, a
 * µTest++ runner runs the suites below; the report goes to the board's
 * console and to the runner (see ../../mtp/README.md), and the run ends with
 * the RESULT line the runner reads.
 *
 *   00 - Cores     the other cores joined (boards with SMP boot helpers)
 *   01 - Runtime   what every µTest++ board must provide: the boot code ran
 *                  the static constructors, malloc works, the heap and sbrk
 *                  agree with the linker script's heap
 *   02 - Basics    a few checks to copy from
 *
 * Copy this directory to mtp-<name> to start a new test: any mtp-*
 * directory gets µTest++ and the board support from tests.cmake.
 */
#include <mtp_board.hpp>

void suite_runtime (mt::suite& ts);
void suite_basics (mt::suite& ts);

mt::runner tr;

int
os_main (int, char*[])
{
  mtp_board::start ("mtp-example");
#if defined(MTP_HAS_SMP_BOOT) && MTP_HAS_SMP_BOOT
  mtp_board::release_cores ();
#endif
  tr.initialise (mtp_board::options ());
#if defined(MTP_HAS_SMP_BOOT) && MTP_HAS_SMP_BOOT
  tr.add_suite ("00 - Cores", mtp_board::suite_cores);
#endif
  tr.add_suite ("01 - Runtime", suite_runtime);
  tr.add_suite ("02 - Basics", suite_basics);
  return mtp_board::finish (tr.run_suites ());
}

#include <mtp_startup.hpp>
